mapper.select:
SELECT FROM telemetry_destinations d WHERE d.organization_uuid = #{organizationUUID} AND d.deleted_at IS NULL
AND (d.workspace_scope = 'all' OR (d.workspace_scope = 'include' AND EXISTS ( SELECT 1 FROM telemetry_destination_workspaces w WHERE w.destination_uuid = d.uuid AND w.organization_uuid = d.organization_uuid AND w.workspace_uuid IN #{workspaceUUID})) OR (d.workspace_scope = 'exclude' AND EXISTS ( SELECT 1 FROM unnest(ARRAY[CAST(#{candidateUUID} AS uuid)]) AS candidate(workspace_uuid) WHERE NOT EXISTS ( SELECT 1 FROM telemetry_destination_workspaces w WHERE w.destination_uuid = d.uuid AND w.organization_uuid = d.organization_uuid AND w.workspace_uuid = candidate.workspace_uuid))))
ORDER BY d.created_at ASC, d.uuid ASC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE telemetry_destinations SET last_test_at = #{now}
WHERE organization_uuid = #{organizationUUID} AND external_id = #{externalID} AND deleted_at IS NULL
  AND (last_test_at IS NULL OR last_test_at <= #{notAfter})

